svg.script:
(() => {
  const descriptions = {
    'budget-step': document.getElementById('curve-description').dataset.budgetDescription,
    'frontier-linear': 'Pareto frontier: straight segments connect consecutive non-dominated models',
    none: 'Points only: no summary curve is displayed'
  };
  const setCurve = (selected) => {
    document.getElementById('curve-budget-step').style.display = selected === 'budget-step' ? '' : 'none';
    document.getElementById('curve-frontier-linear').style.display = selected === 'frontier-linear' ? '' : 'none';
    document.getElementById('curve-description').textContent = descriptions[selected];
    document.querySelectorAll('.curve-control').forEach((control) => {
      const active = control.dataset.curve === selected;
      control.classList.toggle('active', active);
      control.setAttribute('aria-checked', String(active));
    });
  };
  window.setCapabilityCurve = setCurve;
  document.querySelectorAll('.curve-control').forEach((control) => {
    const select = () => setCurve(control.dataset.curve);
    control.addEventListener('click', select);
    control.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); select(); }
    });
  });
  const setFilter = (control, checked) => {
    const kind = control.dataset.filter;
    control.setAttribute('aria-checked', String(checked));
    document.getElementById(`filter-${kind}-mark`).style.display = checked ? '' : 'none';
    document.querySelectorAll(`.model-${kind}`).forEach((model) => { model.style.display = checked ? '' : 'none'; });
  };
  document.querySelectorAll('.filter-control').forEach((control) => {
    const toggle = () => setFilter(control, control.getAttribute('aria-checked') !== 'true');
    control.addEventListener('click', toggle);
    control.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); toggle(); }
    });
  });
})();
